         {/* --- CORNERS (1 - 4) --- */}
      {moduleLayout === 'corner' && (<>
        {renderModule('C1', cornerBottomLeft, {}, 'corner-1')}
        {renderModule('C3', cornerTopLeft, {}, 'corner-2')}
        {renderModule('C2', cornerBottomRight, {}, 'corner-3')}
        {renderModule('C4', cornerTopRight, {}, 'corner-4')}
      </>)}
      {moduleLayout === 'beacon' && (<>
        {renderModule('B1', beaconleft, {}, 'beacon-1')}
        {renderModule('B2', beaconright, {}, 'beacon-2')}
      </>)}

       
        {/* Dropdown-selected front/rear modules */}
        {visibleFrontRearSlots.map((slotKey) => {
          const shape = frontRearModuleShapes[slotKey];
          if (!shape) return null;
          const slot = slotData?.[slotKey];
          const fill = slot && slot.active !== false ? getFill(slotKey) : '#a7a9ac';
          const selected = isSelected(slotKey);
          return (
            <g key={`front-rear-${slotKey}`}>
              <polygon points={shape.points} fill={fill} stroke={selected ? '#38bdf8' : '#231f20'} strokeWidth={selected ? 1.8 : 0.8} style={{ cursor: 'pointer' }} onClick={() => onSelectSlot(slotKey)} />
              <text x={shape.labelX} y={shape.labelY} textAnchor="middle" dominantBaseline="middle" fontSize="7" fontWeight="700" fill="#231f20" style={{ cursor: 'pointer', pointerEvents: 'none' }}>I{slotKey}</text>
            </g>
          );
        })}


           {/* --- OUTER MODULE NUMBERS: match the currently displayed paths --- */}
        {moduleLayout === 'corner' && (<>
          <text className="cls-num" onClick={() => onSelectSlot('C1')} transform="translate(60 134)"><tspan x="0" y="0">C1</tspan></text>
          <text className="cls-num" onClick={() => onSelectSlot('C2')} transform="translate(540 134)"><tspan x="0" y="0">C2</tspan></text>
          <text className="cls-num" onClick={() => onSelectSlot('C3')} transform="translate(60 50)"><tspan x="0" y="0">C3</tspan></text>
          <text className="cls-num" onClick={() => onSelectSlot('C4')} transform="translate(540 50)"><tspan x="0" y="0">C4</tspan></text>
        </>)}
        {moduleLayout === 'beacon' && (<>
          <text className="cls-num" onClick={() => onSelectSlot('B1')} transform="translate(46 91)"><tspan x="0" y="0">B1</tspan></text>
          <text className="cls-num" onClick={() => onSelectSlot('B2')} transform="translate(544 91)"><tspan x="0" y="0">B2</tspan></text>
        </>)}

